{
  "outcome": "patch",
  "candidate_reviews": {
    "C001": {
      "decision": "edit",
      "reason": "The generated C# property for the renamed proto field 'ground_speed_mps' (wire field 2) is 'GroundSpeedMps' following PascalCase convention. The construction uses the old property name 'SpeedMps' which must be updated."
    },
    "C002": {
      "decision": "edit",
      "reason": "The runtime observation key must change from 'speed_mps' to 'ground_speed_mps' per intended_behavior. The property access changes from entity.SpeedMps to entity.GroundSpeedMps to match the regenerated bindings."
    },
    "C003": {
      "decision": "edit",
      "reason": "The speeding predicate uses entity.SpeedMps which must be updated to entity.GroundSpeedMps to reference the correct regenerated property. The threshold 30.0 and strict greater-than comparison are preserved."
    }
  },
  "edits": [
    {
      "before": "            var sample = new Simulation.Telemetry.VehicleTelemetry { VehicleId = request.VehicleId, SpeedMps = request.Speed };\n",
      "after": "            var sample = new Simulation.Telemetry.VehicleTelemetry { VehicleId = request.VehicleId, GroundSpeedMps = request.Speed };\n"
    },
    {
      "before": "            var fields = new Dictionary<string, object> { [\"vehicle_id\"] = entity.VehicleId, [\"speed_mps\"] = entity.SpeedMps };\n",
      "after": "            var fields = new Dictionary<string, object> { [\"vehicle_id\"] = entity.VehicleId, [\"ground_speed_mps\"] = entity.GroundSpeedMps };\n"
    },
    {
      "before": "            return new { fields, speeding = entity.SpeedMps > 30.0, constructed_payload = Convert.ToBase64String(sample.ToByteArray()) };\n",
      "after": "            return new { fields, speeding = entity.GroundSpeedMps > 30.0, constructed_payload = Convert.ToBase64String(sample.ToByteArray()) };\n"
    }
  ],
  "rationale": "All three candidates reference the renamed proto field (wire field 2). The regenerated C# bindings expose it as 'GroundSpeedMps' (PascalCase). The observation key changes from 'speed_mps' to 'ground_speed_mps' per intended_behavior. The speeding threshold remains a strict greater-than 30.0 comparison using the decoded float32 value widened to double in C#. VehicleId and payload handling are unchanged.",
  "confidence": 0.95,
  "assumptions": [
    "Protobuf C# generator produces property 'GroundSpeedMps' for field 'ground_speed_mps'",
    "request.Speed (float) maps correctly to the float32 field",
    "No other runtime files require updates for this schema change"
  ]
}
